	private static void createSymbolicLinkOrSkip(Path link, Path target) throws IOException {
		try {
			Files.createSymbolicLink(link, target);
		} catch (IOException | UnsupportedOperationException | SecurityException e) {
			assumeTrue(false, "Symbolic links are unavailable in this test environment: " + e.getMessage());
		}
	}

	private static URLStreamHandler httpSource(byte[] body) {
		return new URLStreamHandler() {
			@Override
			protected URLConnection openConnection(URL url) {
				return new HttpURLConnection(url) {
					@Override
					public void disconnect() {
					}

					@Override
					public boolean usingProxy() {
						return false;
					}

					@Override
					public void connect() {
					}

					@Override
					public int getResponseCode() {
						return 200;
					}

					@Override
					public java.io.InputStream getInputStream() {
						return new ByteArrayInputStream(body);
					}
				};
			}
		};
	}

	private static MockHttpServletResponse postServerFile(AddServlet servlet, String name) throws Exception {
		WorkbenchRequest request = mock(WorkbenchRequest.class);
		when(request.getParameter("Content-Type")).thenReturn("autodetect");
		when(request.isParameterPresent("server-file")).thenReturn(true);
		when(request.getParameter("server-file")).thenReturn(name);
		MockHttpServletResponse response = new MockHttpServletResponse();
		servlet.doPost(request, response);
		return response;
	}

	private static void restoreProperty(String name, String previous) {
		if (previous == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, previous);
		}
	}

